def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find smallest diagonal-periodic pattern consistent with every clue.
    for period in range(1, max(h, w) + 1):
        seq = {}
        consistent = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = (c-r) % period
                    if k in seq and seq[k] != v:
                        consistent = False
                        break
                    seq[k] = v
            if not consistent:
                break
        if consistent and len(seq) == period:
            return [[seq[(c-r) % period] for c in range(w)] for r in range(h)]
    # Fallback: fill via repeating diagonal motif from observed offsets.
    seq = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]: seq[c-r] = grid[r][c]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = seq.get(c-r, 0)
    return out
