def transform(grid):
    h, w = len(grid), len(grid[0])
    # The clues mark parallel diagonals; their colors define a repeating
    # diagonal stripe sequence. Order clue bands by offset, then cycle colors.
    bands = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                bands[c-r] = grid[r][c]
    ds = sorted(bands)
    if not ds:
        return [row[:] for row in grid]
    colors = [bands[d] for d in ds]
    # Use observed spacing as period positions, preserving intervening bands
    # by cyclically repeating the clue colors.
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            d = c-r
            idx = min(range(len(ds)), key=lambda i: (abs(ds[i]-d), i))
            row.append(colors[idx])
        out.append(row)
    return out
